 * Errors the CLI can raise. `CliError` carries the exit code the process
 * should use and the single line that should be written to standard error.
 * `CycleError` is a distinct type because its exit code (3) and message
 * shape differ from every other failure (exit code 2).
 */

export class CliError extends Error {
  constructor(message, exitCode = 2) {
    super(message)
    this.exitCode = exitCode
  }
}

export class CycleError extends Error {
  constructor(cyclePath) {
    super(`cycle: ${cyclePath.join(' -> ')}`)
    this.cyclePath = cyclePath
    this.exitCode = 3
  }
}
"}

