{"file_path":"src/parse.js","content":"/**
 * Turns the raw standard-input text into a build graph: a map of task
 * names to costs and a map of task names to the set of names they depend
 * on. Every syntactic problem is reported as a `CliError` naming the line
 * it was found on; an unknown task referenced by a `dep` line is reported
 * without a line number once the whole input has been read, matching the
 * order the specification describes.
 */

import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set(name)
  const usageOrder = [] // names referenced by dep lines, in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const source = words[1]
      const dependencies = words.slice(2)
      usageOrder.push(source)
      if (!deps.has(source)) deps.set(source, new Set())
      const set = deps.get(source)
      for (const dep of dependencies) {
        usageOrder.push(dep)
        set.add(dep)
      }
    } else {
      throw new CliError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const name of usageOrder) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`)
    }
  }

  return { tasks, deps }
}
"}

