{"file_path":"src/graph.js","content":"/**
 * Analyses a parsed build graph: cycle detection, the unlimited-worker
 * timing used by `waves` and `explain`, and the worker-constrained
 * simulation used by `pack`.
 */

import { CycleError } from './errors.js'

/**
 * Depth-first search for a cycle, starting from each task in ascending
 * name order and walking each task's dependencies in ascending name
 * order, exactly as the specification requires. Returns the cycle path
 * (ending with a repeat of its first name) or null when the graph is
 * acyclic.
 */
export function findCycle(tasks, deps) {
  const state = new Map() // name -> 'visiting' | 'done'
  const stack = []
  const sortedNames = [...tasks.keys()].sort()

  function visit(node) {
    state.set(node, 'visiting')
    stack.push(node)
    const depSet = deps.get(node) || new Set()
    const sortedDeps = [...depSet].sort()
    for (const dep of sortedDeps) {
      const depState = state.get(dep)
      if (depState === 'visiting') {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat(dep)
      }
      if (depState !== 'done') {
        const found = visit(dep)
        if (found) return found
      }
    }
    state.set(node, 'done')
    stack.pop()
    return null
  }

  for (const name of sortedNames) {
    if (state.get(name) !== 'done') {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

export function checkForCycle(tasks, deps) {
  const cycle = findCycle(tasks, deps)
  if (cycle) throw new CycleError(cycle)
}

/**
 * Computes, for every task, the start/finish/depth triple described by
 * the specification, assuming the graph is acyclic.
 */
export function computeTiming(tasks, deps) {
  const info = new Map() // name -> { start, finish, depth }

  function getInfo(name) {
    if (info.has(name)) return info.get(name)
    const depSet = deps.get(name) || new Set()
    const cost = tasks.get(name)
    let result
    if (depSet.size === 0) {
      result = { start: 0, finish: cost, depth: 0 }
    } else {
      let maxFinish = 0
      let maxDepth = -1
      for (const dep of depSet) {
        const depInfo = getInfo(dep)
        if (depInfo.finish > maxFinish) maxFinish = depInfo.finish
        if (depInfo.depth > maxDepth) maxDepth = depInfo.depth
      }
      result = { start: maxFinish, finish: maxFinish + cost, depth: maxDepth + 1 }
    }
    info.set(name, result)
    return result
  }

  for (const name of tasks.keys()) getInfo(name)
  return info
}

/**
 * Priority for the `pack` scheduler: the cost of the longest chain that
 * begins at a task, following the tasks that depend on it, down to a
 * task nothing depends on.
 */
function computePriorities(tasks, deps) {
  const consumers = new Map() // name -> Set(name) of tasks that depend on it
  for (const [source, depSet] of deps) {
    for (const dep of depSet) {
      if (!consumers.has(dep)) consumers.set(dep, new Set())
      consumers.get(dep).add(source)
    }
  }

  const priority = new Map()
  function getPriority(name) {
    if (priority.has(name)) return priority.get(name)
    const cons = consumers.get(name) || new Set()
    let maxDown = 0
    for (const consumer of cons) {
      const p = getPriority(consumer)
      if (p > maxDown) maxDown = p
    }
    const result = tasks.get(name) + maxDown
    priority.set(name, result)
    return result
  }

  for (const name of tasks.keys()) getPriority(name)
  return priority
}

/**
 * Simulates the graph on `workerCount` workers, returning the per-worker
 * run lists and the makespan.
 */
export function packSchedule(tasks, deps, workerCount) {
  const names = [...tasks.keys()]
  const priority = computePriorities(tasks, deps)

  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, log: [] }))
  const finishTime = new Map()
  const started = new Set()

  const isReady = (name, time) => {
    const depSet = deps.get(name) || new Set()
    for (const dep of depSet) {
      const f = finishTime.get(dep)
      if (f === undefined || f > time) return false
    }
    return true
  }

  let time = 0
  let scheduled = 0
  const total = names.length

  while (scheduled < total) {
    for (;;) {
      const freeWorkerIndices = []
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= time) freeWorkerIndices.push(i)
      }
      if (freeWorkerIndices.length === 0) break

      let best = null
      for (const name of names) {
        if (started.has(name)) continue
        if (!isReady(name, time)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const workerIndex = freeWorkerIndices[0]
      const cost = tasks.get(best)
      const start = time
      const finish = time + cost
      workers[workerIndex].freeAt = finish
      workers[workerIndex].log.push({ name: best, start, finish })
      finishTime.set(best, finish)
      started.add(best)
      scheduled++
    }

    if (scheduled >= total) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.freeAt > time && worker.freeAt < next) next = worker.freeAt
    }
    if (next === Infinity) break // should not happen for a well-formed acyclic graph
    time = next
  }

  const makespan = workers.reduce((max, w) => {
    const last = w.log[w.log.length - 1]
    return last ? Math.max(max, last.finish) : max
  }, 0)

  return { workers, makespan }
}
"}

