const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE)
}

function runWaves(tasks, deps) {
  const timing = computeTiming(tasks, deps)
  const byDepth = new Map()
  let maxFinish = 0
  for (const [name, info] of timing) {
    if (!byDepth.has(info.depth)) byDepth.set(info.depth, [])
    byDepth.get(info.depth).push(name)
    if (info.finish > maxFinish) maxFinish = info.finish
  }
  const lines = []
  const maxDepth = byDepth.size === 0 ? -1 : Math.max(...byDepth.keys())
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (byDepth.get(depth) || []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  lines.push(`total ${maxFinish}`)
  return lines.join('\n') + '\n'
}

function runExplain(tasks, deps) {
  const timing = computeTiming(tasks, deps)
  const names = [...tasks.keys()].sort()
  let maxFinish = 0
  const lines = []
  for (const name of names) {
    const info = timing.get(name)
    if (info.finish > maxFinish) maxFinish = info.finish
    lines.push(`${name} start=${info.start} finish=${info.finish} depth=${info.depth}`)
  }
  lines.push(`total ${maxFinish}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, deps, workerCount) {
  const { workers, makespan } = packSchedule(tasks, deps, workerCount)
  const lines = workers.map((worker, i) => {
    const parts = worker.log.map((entry) => `${entry.name}@${entry.start}-${entry.finish}`)
    return parts.length === 0 ? `worker ${i}:` : `worker ${i}: ${parts.join(' ')}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

