  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  checkForCycle(tasks, deps)

  let output
  if (args.mode === 'waves') {
    output = runWaves(tasks, deps)
  } else if (args.mode === 'explain') {
    output = runExplain(tasks, deps)
  } else {
    output = runPack(tasks, deps, args.workers)
  }
  process.stdout.write(output)
